import{_ as e,C as t,o as p,c as l,j as s,a as r,G as i,a3 as o}from"./chunks/framework.exbasbhr.js";const P=JSON.parse('{"title":"仓库结构总览","description":"解决方案内各项目的职责划分，以及 sln 之外的组件","frontmatter":{"title":"仓库结构总览","description":"解决方案内各项目的职责划分，以及 sln 之外的组件"},"headers":[],"relativePath":"cn/dev/project-structure.md","filePath":"cn/dev/project-structure.md"}'),c={name:"cn/dev/project-structure.md"};function d(b,n,u,m,h,g){const a=t("ArticleMetadata");return p(),l("div",null,[n[0]||(n[0]=s("h1",{id:"仓库结构总览",tabindex:"-1"},[r("仓库结构总览 "),s("a",{class:"header-anchor",href:"#仓库结构总览","aria-label":'Permalink to "仓库结构总览"'},"​")],-1)),i(a),n[1]||(n[1]=o(`<h2 id="解决方案内的项目" tabindex="-1">解决方案内的项目 <a class="header-anchor" href="#解决方案内的项目" aria-label="Permalink to &quot;解决方案内的项目&quot;">​</a></h2><p><code>Ink Canvas.sln</code> 包含 6 个项目：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>InkCanvasForClass</strong></td><td>主程序（WPF）。窗口、画布、工具栏、设置、PPT 联动等主体逻辑</td></tr><tr><td><strong>InkCanvas.PluginSdk</strong></td><td>插件 SDK，第三方插件编译时引用的契约程序集</td></tr><tr><td><strong>InkCanvas.Controls</strong></td><td>可复用的自定义控件库</td></tr><tr><td><strong>InkCanvas.IACoreHelper</strong></td><td>IACore 手写识别辅助进程</td></tr><tr><td><strong>InkCanvas.SettingsTreeView</strong></td><td>设置界面使用的树形导航控件</td></tr><tr><td><strong>InkCanvas.PptAgent.Contracts</strong></td><td>主程序与 PowerPoint 加载项之间的通信契约</td></tr></tbody></table><h2 id="解决方案之外的组件" tabindex="-1">解决方案之外的组件 <a class="header-anchor" href="#解决方案之外的组件" aria-label="Permalink to &quot;解决方案之外的组件&quot;">​</a></h2><p>仓库里还有几个<strong>不在 sln 中</strong>的目录，需要单独构建：</p><ul><li><strong>InkCanvas.PowerPointAddIn</strong> —— VSTO 加载项，安装到 PowerPoint 中，把放映事件推送给主程序</li><li><strong>InkCanvas.NativeInk.Tests</strong> —— 原生墨迹管线的测试项目</li><li><strong>inkore-mcp</strong> —— Python 实现的 MCP 服务，与主程序构建无关</li></ul><div class="tip custom-block"><p class="custom-block-title">只想编译主程序</p><p>直接打开 <code>Ink Canvas.sln</code> 即可，上述三个目录不会被牵连。</p></div><h2 id="主程序内部目录" tabindex="-1">主程序内部目录 <a class="header-anchor" href="#主程序内部目录" aria-label="Permalink to &quot;主程序内部目录&quot;">​</a></h2><p><code>Ink Canvas/</code> 下按职责分目录：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ink Canvas/</span></span>
<span class="line"><span>├── MainWindow_cs/     主窗口的 42 个 partial 分部文件</span></span>
<span class="line"><span>├── Ink/</span></span>
<span class="line"><span>│   └── Native/        基于 Vortice 的原生低延迟墨迹管线</span></span>
<span class="line"><span>├── Automation/        自动化规则引擎</span></span>
<span class="line"><span>├── IPC/               与 PPT 加载项的管道客户端</span></span>
<span class="line"><span>├── Controls/          主程序内的控件</span></span>
<span class="line"><span>├── Helpers/           各类辅助类</span></span>
<span class="line"><span>├── Plugins/           插件宿主</span></span>
<span class="line"><span>├── Windows/           设置等独立窗口</span></span>
<span class="line"><span>├── Models/            数据模型</span></span>
<span class="line"><span>├── MarkupExtensions/  XAML 标记扩展</span></span>
<span class="line"><span>├── Resources/         资源</span></span>
<span class="line"><span>└── libs/              外部依赖</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="关于-mainwindow-的-42-个分部文件" tabindex="-1">关于 MainWindow 的 42 个分部文件 <a class="header-anchor" href="#关于-mainwindow-的-42-个分部文件" aria-label="Permalink to &quot;关于 MainWindow 的 42 个分部文件&quot;">​</a></h3><p>主窗口的逻辑非常庞大，因此被拆成 42 个 <code>partial class</code> 文件放在 <code>MainWindow_cs/</code> 下， 按功能划分（工具栏、页面列表、手势、PPT 等）。</p><p>修改主窗口逻辑时：</p><ul><li>先按功能找到对应的分部文件，不要把新代码堆到主文件里</li><li>新增一块相对独立的功能时，倾向于新建一个分部文件</li><li>分部文件之间共享字段，改动前留意其他文件是否也在用同一个字段</li></ul><h2 id="automation-规则引擎" tabindex="-1">Automation 规则引擎 <a class="header-anchor" href="#automation-规则引擎" aria-label="Permalink to &quot;Automation 规则引擎&quot;">​</a></h2><p><code>Automation/</code> 是一套独立的规则引擎，结构清晰：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Automation/</span></span>
<span class="line"><span>├── AutomationBootstrap.cs   启动装配入口</span></span>
<span class="line"><span>├── Abstractions/            接口定义</span></span>
<span class="line"><span>├── Triggers/                触发器：什么时候触发</span></span>
<span class="line"><span>├── Rules/                   规则：触发后判断是否执行</span></span>
<span class="line"><span>├── Actions/                 动作定义</span></span>
<span class="line"><span>├── ActionHandlers/          动作的实际执行</span></span>
<span class="line"><span>├── Services/                支撑服务</span></span>
<span class="line"><span>├── Models/  Enums/  Extensions/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>扩展方式是新增 Trigger / Action / ActionHandler 的实现并注册到 Bootstrap，而不是修改现有分支逻辑。</p><h2 id="原生墨迹管线" tabindex="-1">原生墨迹管线 <a class="header-anchor" href="#原生墨迹管线" aria-label="Permalink to &quot;原生墨迹管线&quot;">​</a></h2><p><code>Ink/Native/</code> 是基于 <strong>Vortice</strong>（Direct3D/Direct2D 的 .NET 绑定）实现的低延迟湿墨迹渲染路径， 与 WPF 传统 <code>InkCanvas</code> 构成<strong>双渲染路径</strong>：</p><ul><li><strong>原生路径</strong>：正在书写的湿墨迹直接走 GPU 渲染，延迟更低</li><li><strong>传统路径</strong>：落笔完成后的干墨迹交给 WPF InkCanvas 管理，保证兼容性与既有功能</li></ul><p>改动这部分时务必两条路径同时验证，只测其中一条很容易漏掉视觉差异。 <code>InkCanvas.NativeInk.Tests</code> 就是为这条管线准备的测试项目。</p><h2 id="iacore-跨架构调用" tabindex="-1">IACore 跨架构调用 <a class="header-anchor" href="#iacore-跨架构调用" aria-label="Permalink to &quot;IACore 跨架构调用&quot;">​</a></h2><p>手写识别依赖的 IACore 组件<strong>只有 32 位版本</strong>，而主程序通常以 64 位运行。 因此识别功能被拆到独立的 <code>InkCanvas.IACoreHelper</code> 进程中，由主程序通过进程间通信调用。</p><p>这意味着：</p><ul><li>识别相关的问题要同时看主程序与辅助进程两边的日志</li><li>辅助进程意外退出时，主程序需要能容错并重启它</li><li>调试识别功能时需要附加到辅助进程，而不是主进程</li></ul><h2 id="ppt-联动的三方关系" tabindex="-1">PPT 联动的三方关系 <a class="header-anchor" href="#ppt-联动的三方关系" aria-label="Permalink to &quot;PPT 联动的三方关系&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主程序 InkCanvasForClass</span></span>
<span class="line"><span>   │  IPC/PPTAgentPipeClient.cs（管道客户端）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── InkCanvas.PptAgent.Contracts（双方共享的消息契约）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   └── InkCanvas.PowerPointAddIn（VSTO 加载项，运行在 PowerPoint 进程内）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>修改通信协议时，<strong>契约项目要与两端同时更新</strong>，否则会出现一端能发不能收的情况。 加载项不在 sln 内，改完记得单独构建并重新部署到 PowerPoint。</p>`,29))])}const k=e(c,[["render",d]]);export{P as __pageData,k as default};
